var symbolIconFrag = "#include \"_prelude_lighting.glsl\"\n\nuniform sampler2D u_texture;\n#ifdef ICON_TRANSITION\nuniform float u_icon_transition;\n#endif\n\nin float v_fade_opacity;\nin vec2 v_tex_a;\n#ifdef ICON_TRANSITION\nin vec2 v_tex_b;\n#endif\n\n#ifdef COLOR_ADJUSTMENT\nuniform mat4 u_color_adj_mat;\n#endif\n\n#pragma mapbox: define lowp float opacity\n#pragma mapbox: define lowp float emissive_strength\n\nvoid main() {\n    #pragma mapbox: initialize lowp float opacity\n    #pragma mapbox: initialize lowp float emissive_strength\n\n    lowp float alpha = opacity * v_fade_opacity;\n    vec4 out_color;\n\n#ifdef ICON_TRANSITION\n    vec4 a = texture(u_texture, v_tex_a) * (1.0 - u_icon_transition);\n    vec4 b = texture(u_texture, v_tex_b) * u_icon_transition;\n    out_color = (a + b);\n#else\n    out_color = texture(u_texture, v_tex_a);\n#endif\n\n#ifdef COLOR_ADJUSTMENT\n    out_color = u_color_adj_mat * out_color;\n#endif\n\n    out_color *= alpha;\n\n#ifdef LIGHTING_3D_MODE\n    out_color = apply_lighting_with_emission_ground(out_color, emissive_strength);\n#endif\n\n    glFragColor = out_color;\n\n#ifdef OVERDRAW_INSPECTOR\n    glFragColor = vec4(1.0);\n#endif\n\n    \n\n    HANDLE_WIREFRAME_DEBUG;\n}\n";

